'use client'

import { useEffect, useState } from 'react'

type DashboardData = {
  analytics: unknown
  notifications: unknown
  settings: unknown
}

export default function Dashboard() {
  const [data, setData] = useState<DashboardData | null>(null)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const controller = new AbortController()

    async function getJson(path: string) {
      const response = await fetch(path, { signal: controller.signal })
      if (!response.ok) {
        throw new Error(`Failed to load ${path} (${response.status})`)
      }
      return response.json()
    }

    async function loadDashboard() {
      try {
        const [analytics, notifications, settings] = await Promise.all([
          getJson('/api/analytics'),
          getJson('/api/notifications'),
          getJson('/api/settings'),
        ])

        if (!controller.signal.aborted) {
          setData({ analytics, notifications, settings })
        }
      } catch (cause) {
        if (!controller.signal.aborted) {
          setError(cause instanceof Error ? cause.message : 'Failed to load dashboard data')
        }
      }
    }

    void loadDashboard()
    return () => controller.abort()
  }, [])

  return (
    <div>
      <h2>Dashboard Content</h2>
      {error ? (
        <p role="alert">{error}</p>
      ) : data ? (
        (['analytics', 'notifications', 'settings'] as const).map((section) => (
          <section key={section}>
            <h3>{section[0].toUpperCase() + section.slice(1)}</h3>
            <pre>{JSON.stringify(data[section], null, 2)}</pre>
          </section>
        ))
      ) : (
        <p role="status">Loading dashboard data...</p>
      )}
    </div>
  )
}

